namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with fake initial data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notifications page!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post."),
        });
    }

    /// <summary>Returns all notifications up to this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications with Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>Simulates new notifications arriving over time.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            // ~30 % chance of a new notification each call.
            if (Random.Shared.Next(100) < 30)
            {
                _notifications.Add(CreateNotification($"Event fired at {DateTime.Now:T}"));
            }
        }
    }

    private Notification CreateNotification(string message) =>
        new(_nextId++, message, DateTime.Now);
}

@page "/notifications"
@using NotificationsApp.Services
@rendermode InteractiveServer
@inject NotificationService Svc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h2>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h2>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@if (_isPolling)
{
    <p class="mt-3 text-success"><em>Live — polling for new notifications…</em></p>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private bool _isPolling;

    // Runs during SSR *and* on the interactive reconnect.
    // Because the component is re-created for the interactive circuit,
    // this always fires — but it just reads the service snapshot,
    // so the initial data from SSR is never wasted (same source of truth).
    protected override void OnInitialized()
    {
        _notifications = Svc.GetAll();
    }

    // Only called once the circuit is live (never during static SSR).
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _isPolling = true;
            StateHasChanged();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        var lastSeenId = _notifications.Count > 0
            ? _notifications[^1].Id
            : 0;

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(5000, ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            // Simulate external events arriving.
            Svc.SimulateIncoming();

            var newItems = Svc.GetSince(lastSeenId);
            if (newItems.Count > 0)
            {
                _notifications.AddRange(newItems);
                lastSeenId = newItems[^1].Id;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

